// analyzer/properties.ts:45
pub fn validate_property_method(
    evaluator: &TypeEvaluator,
    method: FunctionType,
    error_node: P<ParseNode>,
) {
    if FunctionType::is_static_method(method) {
        evaluator.add_diagnostic(
            DiagnosticRule::reportGeneralTypeIssues,
            &LocMessage::property_static_method(),
            error_node,
            None,
        );
    }
}

// analyzer/properties.ts:51
pub fn create_property(
    evaluator: &TypeEvaluator,
    decorator_node: DecoratorNode,
    decorator_type: ClassType,
    fget: FunctionType,
    node_info: &AnalyzerNodeInfoAccessor,
) -> ClassType {
    let file_info = node_info.get_file_info(decorator_node.0);
    let type_metaclass = evaluator.get_built_in_type(decorator_node.0, "type");
    let decorator_shared = decorator_type.d().shared.get();
    let type_source_id = if ClassType::is_built_in(decorator_type, Some(&["property"]))
    {
        get_type_source_id(decorator_node.0)
    } else {
        decorator_shared.type_source_id
    };

    let property_class = ClassType::create_instantiable(
        &decorator_shared.name,
        &get_class_full_name(
            decorator_node.0,
            &file_info.module_name,
            &format!("__property_{}", fget.d().shared.get().name),
        ),
        &file_info.module_name,
        &file_info.file_uri,
        ClassTypeFlags::PropertyClass | ClassTypeFlags::BuiltIn,
        type_source_id,
        /* declaredMetaclass */ None,
        Some(if is_instantiable_class(type_metaclass) {
            type_metaclass
        } else {
            UnknownType::create(false).0
        }),
        None,
    );

    let property_shared = property_class.d().shared.get();
    property_shared
        .declaration
        .set(decorator_shared.declaration.get());
    let type_var_scope_id = decorator_shared.type_var_scope_id.borrow().clone();
    *property_shared.type_var_scope_id.borrow_mut() = type_var_scope_id;
    let object_type = evaluator.get_built_in_type(decorator_node.0, "object");
    property_shared
        .base_classes
        .borrow_mut()
        .push(if is_instantiable_class(object_type) {
            object_type
        } else {
            UnknownType::create(false).0
        });
    compute_mro_linearization(property_class);

    // Clone the symbol table of the old class type.
    let fields = ClassType::get_symbol_table(property_class);
    ClassType::get_symbol_table(decorator_type).for_each(|symbol, name| {
        let ignored_methods = ["__get__", "__set__", "__delete__"];

        if !symbol.is_ignored_for_protocol_match() && !ignored_methods.contains(&name) {
            fields.set(name, symbol);
        }
    });

    let property_object = ClassType::clone_as_instance(property_class, true);
    property_class
        .d()
        .priv_
        .borrow_mut()
        .cold_mut().is_asymmetric_descriptor = Some(false);

    // Update the __set__ and __delete__ methods if present.
    update_get_set_del_method_for_cloned_property(evaluator, property_object);

    // Fill in the fget method.
    let fget_info = PropertyMethodInfo {
        method_type: fget.0,
        class_type: fget.d().shared.get().method_class.get(),
    };
    property_object.d().priv_.borrow_mut().cold_mut().fget_info = Some(fget_info);

    if FunctionType::is_class_method(fget) {
        property_shared
            .flags
            .set(property_shared.flags.get() | ClassTypeFlags::ClassProperty);
    }

    // Fill in the __get__ method with an overload.
    add_get_method_to_property_symbol_table(evaluator, property_object, fget);

    // Fill in the getter, setter and deleter methods.
    add_decorator_methods_to_property_symbol_table(property_object);

    property_object
}

// analyzer/properties.ts:118
pub fn clone_property_with_setter(
    evaluator: &TypeEvaluator,
    prop: P<Type>,
    fset: FunctionType,
    error_node: FunctionNode,
    node_info: &AnalyzerNodeInfoAccessor,
) -> P<Type> {
    if !is_property(prop) {
        return prop;
    }

    let class_type = ClassType(prop);
    let class_shared = class_type.d().shared.get();
    let flags_to_clone = class_shared.flags.get();
    let mut is_asymmetric_descriptor = class_type
        .d()
        .priv_
        .borrow()
        .cold().is_asymmetric_descriptor
        .unwrap_or(false);

    // Verify parameters for fset.
    // We'll skip this test if the diagnostic rule is disabled because it
    // can be somewhat expensive, especially in code that is not annotated.
    let file_info = node_info.get_file_info(error_node.0);
    if error_node.d().params.borrow().len() >= 2 {
        let type_annotation = get_type_annotation_for_param(error_node, 1);
        if let Some(type_annotation) = type_annotation {
            // Verify consistency of the type.
            let fget_type = evaluator.get_getter_type_from_property(class_type);
            if let Some(fget_type) = fget_type
                && !is_any_or_unknown(fget_type)
            {
                let fset_type = evaluator.get_type_of_annotation(
                    type_annotation,
                    Some(&ExpectedTypeOptions {
                        type_var_gets_cur_scope: Some(true),
                        ..Default::default()
                    }),
                );

                // The setter type should be assignable to the getter type.
                if file_info.diagnostic_rule_set.report_property_type_mismatch
                    != DiagnosticLevel::None
                {
                    let diag = DiagnosticAddendum::new();
                    if !evaluator.assign_type(
                        fget_type,
                        fset_type,
                        Some(diag),
                        None,
                        AssignTypeFlags::Default,
                        0,
                    ) {
                        evaluator.add_diagnostic(
                            DiagnosticRule::reportPropertyTypeMismatch,
                            &(LocMessage::setter_getter_type_mismatch()
                                + &diag.get_string(
                                    DEFAULT_MAX_DIAGNOSTIC_DEPTH,
                                    DEFAULT_MAX_DIAGNOSTIC_LINE_COUNT,
                                )),
                            type_annotation,
                            None,
                        );
                    }
                }

                if !is_type_same(fget_type, fset_type, &TypeSameOptions::default(), 0) {
                    is_asymmetric_descriptor = true;
                }
            }
        }
    }

    let property_class = ClassType::create_instantiable(
        &class_shared.name,
        &class_shared.full_name,
        &class_shared.module_name,
        &node_info.get_file_info(error_node.0).file_uri,
        flags_to_clone,
        class_shared.type_source_id,
        class_shared.declared_metaclass.get(),
        class_shared.effective_metaclass.get(),
        None,
    );

    let property_shared = property_class.d().shared.get();
    property_shared
        .declaration
        .set(class_shared.declaration.get());
    let type_var_scope_id = class_shared.type_var_scope_id.borrow().clone();
    *property_shared.type_var_scope_id.borrow_mut() = type_var_scope_id;
    let object_type = evaluator.get_built_in_type(error_node.0, "object");
    property_shared
        .base_classes
        .borrow_mut()
        .push(if is_instantiable_class(object_type) {
            object_type
        } else {
            UnknownType::create(false).0
        });
    compute_mro_linearization(property_class);

    let (fget_info, fdel_info) = {
        let class_priv = class_type.d().priv_.borrow();
        (class_priv.cold().fget_info.clone(), class_priv.cold().fdel_info.clone())
    };
    {
        let mut property_priv = property_class.d().priv_.borrow_mut();
        property_priv.cold_mut().fget_info = fget_info;
        property_priv.cold_mut().fdel_info = fdel_info;
        property_priv.cold_mut().is_asymmetric_descriptor = Some(is_asymmetric_descriptor);
    }
    let property_object = ClassType::clone_as_instance(property_class, true);

    // Clone the symbol table of the old class type.
    let fields = ClassType::get_symbol_table(property_class);
    ClassType::get_symbol_table(class_type).for_each(|symbol, name| {
        if !symbol.is_ignored_for_protocol_match() {
            fields.set(name, symbol);
        }
    });

    // Update the __get__ and __delete__ methods if present.
    update_get_set_del_method_for_cloned_property(evaluator, property_object);

    // Combine this setter with any overloaded setters accumulated from previous
    // declarations of this property. This supports overloads on property setters.
    let prev_setter = class_type
        .d()
        .priv_
        .borrow()
        .cold().fset_info
        .as_ref()
        .map(|fset_info| fset_info.method_type);
    let combined_setter = combine_setter_overloads(prev_setter, fset);

    // Fill in the new fset method.
    let fset_info = PropertyMethodInfo {
        method_type: combined_setter,
        class_type: fset.d().shared.get().method_class.get(),
    };
    property_object.d().priv_.borrow_mut().cold_mut().fset_info = Some(fset_info);

    // Fill in the __set__ method.
    add_set_method_to_property_symbol_table(evaluator, property_object, combined_setter);

    // Fill in the getter, setter and deleter methods.
    add_decorator_methods_to_property_symbol_table(property_object);

    property_object.0
}

