// analyzer/properties.ts:278
pub(crate) fn add_get_method_to_property_symbol_table(
    evaluator: &TypeEvaluator,
    property_object: ClassType,
    fget: FunctionType,
) {
    let fields = ClassType::get_symbol_table(property_object);
    let fget_shared = fget.d().shared.get();

    // The first overload is for accesses through a class object (where
    // the instance argument is None).
    let get_function1 =
        FunctionType::create_synthesized_instance("__get__", FunctionTypeFlags::Overloaded);
    FunctionType::add_param(
        get_function1,
        &FunctionParam::create(
            ParamCategory::Simple,
            AnyType::create(false).0,
            FunctionParamFlags::TypeDeclared,
            Some("self"),
            None,
            None,
        ),
    );
    FunctionType::add_param(
        get_function1,
        &FunctionParam::create(
            ParamCategory::Simple,
            evaluator.get_none_type(),
            FunctionParamFlags::TypeDeclared,
            Some("obj"),
            None,
            None,
        ),
    );
    FunctionType::add_param(
        get_function1,
        &FunctionParam::create(
            ParamCategory::Simple,
            AnyType::create(false).0,
            FunctionParamFlags::TypeDeclared,
            Some("objtype"),
            Some(AnyType::create(/* isEllipsis */ true).0),
            None,
        ),
    );
    let get_function1_shared = get_function1.d().shared.get();
    get_function1_shared
        .declared_return_type
        .set(if FunctionType::is_class_method(fget) {
            FunctionType::get_effective_return_type(fget, true)
        } else {
            Some(property_object.0)
        });
    get_function1_shared
        .declaration
        .set(fget_shared.declaration.get());
    let deprecated_message = fget_shared.cold().deprecated_message.clone();
    get_function1_shared.set_cold(|cold| &mut cold.deprecated_message, deprecated_message);
    get_function1_shared
        .method_class
        .set(fget_shared.method_class.get());

    // Override the scope ID since we're using parameter types from the
    // decorated function.
    let type_var_scope_id = get_type_var_scope_id(fget.0);
    *get_function1_shared.type_var_scope_id.borrow_mut() = type_var_scope_id;

    // The second overload is for accesses through a class instance.
    let get_function2 =
        FunctionType::create_synthesized_instance("__get__", FunctionTypeFlags::Overloaded);
    FunctionType::add_param(
        get_function2,
        &FunctionParam::create(
            ParamCategory::Simple,
            AnyType::create(false).0,
            FunctionParamFlags::TypeDeclared,
            Some("self"),
            None,
            None,
        ),
    );

    let obj_type = if !fget_shared.parameters.get().borrow().is_empty() {
        FunctionType::get_param_type(fget, 0)
    } else {
        AnyType::create(false).0
    };

    FunctionType::add_param(
        get_function2,
        &FunctionParam::create(
            ParamCategory::Simple,
            obj_type,
            FunctionParamFlags::TypeDeclared,
            Some("obj"),
            None,
            None,
        ),
    );

    FunctionType::add_param(
        get_function2,
        &FunctionParam::create(
            ParamCategory::Simple,
            AnyType::create(false).0,
            FunctionParamFlags::TypeDeclared,
            Some("objtype"),
            Some(AnyType::create(/* isEllipsis */ true).0),
            None,
        ),
    );
    let get_function2_shared = get_function2.d().shared.get();
    get_function2_shared
        .declared_return_type
        .set(FunctionType::get_effective_return_type(fget, true));
    get_function2_shared
        .declaration
        .set(fget_shared.declaration.get());
    let deprecated_message = fget_shared.cold().deprecated_message.clone();
    get_function2_shared.set_cold(|cold| &mut cold.deprecated_message, deprecated_message);
    get_function2_shared
        .method_class
        .set(fget_shared.method_class.get());

    // Override the scope ID since we're using parameter types from the
    // decorated function.
    let type_var_scope_id = get_type_var_scope_id(fget.0);
    *get_function2_shared.type_var_scope_id.borrow_mut() = type_var_scope_id;

    // We previously placed getFunction1 before getFunction2, but this creates
    // problems specifically for the `NoneType` class because None.__class__
    // is a property, and both overloads match in this case because None
    // is passed for the "obj" parameter.
    let get_function_overload = OverloadedType::create(&[get_function2, get_function1], None);
    let get_symbol =
        Symbol::create_with_type(SymbolFlags::ClassMember, get_function_overload.0, None);
    fields.set("__get__", get_symbol);
}

// analyzer/properties.ts:359
// Combines a newly-decorated setter function with any setter overloads that
// were accumulated from previous declarations of the same property. The
// resulting type is a single FunctionType for a non-overloaded setter or an
// OverloadedType when the setter has overloads.
pub(crate) fn combine_setter_overloads(
    prev_setter: Option<P<Type>>,
    new_setter: FunctionType,
) -> P<Type> {
    // Gather any overload signatures from the previous setter. Note: a lone
    // `@overload` setter with no implementation is represented as a FunctionType
    // with the Overloaded flag set, and is treated as a single overload here. A
    // malformed source with multiple implementations is not specially handled;
    // the most recent implementation wins, consistent with normal functions.
    let mut prev_overloads: Vec<FunctionType> = Vec::new();
    if let Some(prev_setter) = prev_setter {
        if is_overloaded(prev_setter) {
            prev_overloads.extend(OverloadedType::get_overloads(OverloadedType(prev_setter)));
        } else if FunctionType::is_overloaded(FunctionType(prev_setter)) {
            prev_overloads.push(FunctionType(prev_setter));
        }
    }

    if FunctionType::is_overloaded(new_setter) {
        // The new setter is an overload. Append it to the accumulated overloads.
        let mut overloads = prev_overloads.clone();
        overloads.push(new_setter);
        return if overloads.len() > 1 {
            OverloadedType::create(&overloads, None).0
        } else {
            new_setter.0
        };
    }

    // The new setter is not an overload, so it's either a plain setter or the
    // implementation for a set of setter overloads. If there are accumulated
    // overloads, treat it as the implementation; otherwise it's a plain setter.
    if !prev_overloads.is_empty() {
        // Per PEP 702, if the setter implementation is marked @deprecated, all of
        // its overloads inherit the deprecation. This mirrors the behavior of
        // addOverloadsToFunctionType for normal overloaded functions.
        let mut overloads = prev_overloads;
        let new_setter_deprecated_message = new_setter
            .d()
            .shared
            .get()
            .cold().deprecated_message
            .clone();
        if let Some(deprecation_message) = new_setter_deprecated_message {
            overloads = overloads
                .into_iter()
                .map(|overload| {
                    if overload
                        .d()
                        .shared
                        .get()
                        .cold().deprecated_message
                        .is_none()
                    {
                        FunctionType::clone_with_deprecated_message(
                            overload,
                            Some(deprecation_message.clone()),
                        )
                    } else {
                        overload
                    }
                })
                .collect();
        }

        return OverloadedType::create(&overloads, Some(new_setter.0)).0;
    }

    new_setter.0
}

// analyzer/properties.ts:406
pub(crate) fn add_set_method_to_property_symbol_table(
    evaluator: &TypeEvaluator,
    property_object: ClassType,
    fset: P<Type>,
) {
    let fields = ClassType::get_symbol_table(property_object);

    let set_method: P<Type> = if is_overloaded(fset) {
        // Synthesize one __set__ overload per setter overload (excluding the
        // implementation, consistent with normal overloaded function semantics).
        // combineSetterOverloads only produces an OverloadedType when there is at
        // least one overload, so setOverloads is guaranteed to be non-empty here.
        let set_overloads: Vec<FunctionType> = OverloadedType::get_overloads(OverloadedType(fset))
            .into_iter()
            .map(|overload| {
                create_set_method_from_setter(evaluator, overload, /* asOverload */ true)
            })
            .collect();

        if set_overloads.len() > 1 {
            OverloadedType::create(&set_overloads, None).0
        } else {
            set_overloads[0].0
        }
    } else {
        create_set_method_from_setter(evaluator, FunctionType(fset), /* asOverload */ false).0
    };

    let set_symbol = Symbol::create_with_type(SymbolFlags::ClassMember, set_method, None);
    fields.set("__set__", set_symbol);
}

// analyzer/properties.ts:432
pub(crate) fn create_set_method_from_setter(
    evaluator: &TypeEvaluator,
    fset: FunctionType,
    as_overload: bool,
) -> FunctionType {
    let set_function = FunctionType::create_synthesized_instance(
        "__set__",
        if as_overload {
            FunctionTypeFlags::Overloaded
        } else {
            FunctionTypeFlags::None
        },
    );
    FunctionType::add_param(
        set_function,
        &FunctionParam::create(
            ParamCategory::Simple,
            AnyType::create(false).0,
            FunctionParamFlags::TypeDeclared,
            Some("self"),
            None,
            None,
        ),
    );

    let fset_shared = fset.d().shared.get();
    let mut obj_type = if !fset_shared.parameters.get().borrow().is_empty() {
        FunctionType::get_param_type(fset, 0)
    } else {
        AnyType::create(false).0
    };
    if is_type_var(obj_type) && TypeVarType::is_self(TypeVarType(obj_type)) {
        obj_type = evaluator.make_top_level_type_vars_concrete(obj_type, false, None);
    }

    FunctionType::add_param(
        set_function,
        &FunctionParam::create(
            ParamCategory::Simple,
            combine_types(&[obj_type, evaluator.get_none_type()], None),
            FunctionParamFlags::TypeDeclared,
            Some("obj"),
            None,
            None,
        ),
    );

    let set_function_shared = set_function.d().shared.get();
    set_function_shared
        .declared_return_type
        .set(Some(evaluator.get_none_type()));

    // Adopt the TypeVarScopeId of the fset function in case it has any
    // TypeVars that need to be solved.
    let type_var_scope_id = get_type_var_scope_id(fset.0);
    *set_function_shared.type_var_scope_id.borrow_mut() = type_var_scope_id;
    let deprecated_message = fset_shared.cold().deprecated_message.clone();
    set_function_shared.set_cold(|cold| &mut cold.deprecated_message, deprecated_message);
    set_function_shared
        .method_class
        .set(fset_shared.method_class.get());

    let mut set_param_type: P<Type> = UnknownType::create(false).0;

    let has_simple_named_second_param = {
        let parameters = fset_shared.parameters.get();
        let parameters = parameters.borrow();
        parameters.len() >= 2
            && parameters[1].category == ParamCategory::Simple
            && parameters[1]
                .name
                .as_ref()
                .is_some_and(|name| !name.is_empty())
    };
    if has_simple_named_second_param {
        set_param_type = FunctionType::get_param_type(fset, 1);
    }
    FunctionType::add_param(
        set_function,
        &FunctionParam::create(
            ParamCategory::Simple,
            set_param_type,
            FunctionParamFlags::TypeDeclared,
            Some("value"),
            None,
            None,
        ),
    );

    set_function
}

// analyzer/properties.ts:482
pub(crate) fn add_del_method_to_property_symbol_table(
    evaluator: &TypeEvaluator,
    property_object: ClassType,
    fdel: FunctionType,
) {
    let fields = ClassType::get_symbol_table(property_object);

    let del_function =
        FunctionType::create_synthesized_instance("__delete__", FunctionTypeFlags::None);
    FunctionType::add_param(
        del_function,
        &FunctionParam::create(
            ParamCategory::Simple,
            AnyType::create(false).0,
            FunctionParamFlags::TypeDeclared,
            Some("self"),
            None,
            None,
        ),
    );

    // Adopt the TypeVarScopeId of the fdel function in case it has any
    // TypeVars that need to be solved.
    let del_function_shared = del_function.d().shared.get();
    let fdel_shared = fdel.d().shared.get();
    let type_var_scope_id = get_type_var_scope_id(fdel.0);
    *del_function_shared.type_var_scope_id.borrow_mut() = type_var_scope_id;
    let deprecated_message = fdel_shared.cold().deprecated_message.clone();
    del_function_shared.set_cold(|cold| &mut cold.deprecated_message, deprecated_message);
    del_function_shared
        .method_class
        .set(fdel_shared.method_class.get());

    let mut obj_type = if !fdel_shared.parameters.get().borrow().is_empty() {
        FunctionType::get_param_type(fdel, 0)
    } else {
        AnyType::create(false).0
    };

    if is_type_var(obj_type) && TypeVarType::is_self(TypeVarType(obj_type)) {
        obj_type = evaluator.make_top_level_type_vars_concrete(obj_type, false, None);
    }

    FunctionType::add_param(
        del_function,
        &FunctionParam::create(
            ParamCategory::Simple,
            combine_types(&[obj_type, evaluator.get_none_type()], None),
            FunctionParamFlags::TypeDeclared,
            Some("obj"),
            None,
            None,
        ),
    );
    del_function_shared
        .declared_return_type
        .set(Some(evaluator.get_none_type()));
    let del_symbol = Symbol::create_with_type(SymbolFlags::ClassMember, del_function.0, None);
    fields.set("__delete__", del_symbol);
}

// analyzer/properties.ts:517
pub(crate) fn update_get_set_del_method_for_cloned_property(
    evaluator: &TypeEvaluator,
    property_object: ClassType,
) {
    let fget_info = property_object.d().priv_.borrow().cold().fget_info.clone();
    if let Some(fget_info) = fget_info
        && is_function(fget_info.method_type)
    {
        add_get_method_to_property_symbol_table(
            evaluator,
            property_object,
            FunctionType(fget_info.method_type),
        );
    }

    let fset_info = property_object.d().priv_.borrow().cold().fset_info.clone();
    if let Some(fset_info) = fset_info
        && (is_function(fset_info.method_type) || is_overloaded(fset_info.method_type))
    {
        add_set_method_to_property_symbol_table(evaluator, property_object, fset_info.method_type);
    }

    let fdel_info = property_object.d().priv_.borrow().cold().fdel_info.clone();
    if let Some(fdel_info) = fdel_info
        && is_function(fdel_info.method_type)
    {
        add_del_method_to_property_symbol_table(
            evaluator,
            property_object,
            FunctionType(fdel_info.method_type),
        );
    }
}

// analyzer/properties.ts:534
pub(crate) fn add_decorator_methods_to_property_symbol_table(property_object: ClassType) {
    let fields = ClassType::get_symbol_table(property_object);

    // Fill in the getter, setter and deleter methods.
    for accessor_name in ["getter", "setter", "deleter"] {
        let accessor_function =
            FunctionType::create_synthesized_instance(accessor_name, FunctionTypeFlags::None);
        FunctionType::add_param(
            accessor_function,
            &FunctionParam::create(
                ParamCategory::Simple,
                AnyType::create(false).0,
                FunctionParamFlags::TypeDeclared,
                Some("self"),
                None,
                None,
            ),
        );
        FunctionType::add_param(
            accessor_function,
            &FunctionParam::create(
                ParamCategory::Simple,
                AnyType::create(false).0,
                FunctionParamFlags::TypeDeclared,
                Some("accessor"),
                None,
                None,
            ),
        );
        accessor_function
            .d()
            .shared
            .get()
            .declared_return_type
            .set(Some(property_object.0));
        let accessor_symbol =
            Symbol::create_with_type(SymbolFlags::ClassMember, accessor_function.0, None);
        fields.set(accessor_name, accessor_symbol);
    }
}

// analyzer/properties.ts:554
/// TS defaults: recursionCount = 0.
pub fn assign_property(
    evaluator: &TypeEvaluator,
    dest_property_type: ClassType,
    src_property_type: ClassType,
    dest_class: ClassType,
    src_class: P<Type>,
    diag: Option<P<DiagnosticAddendum>>,
    constraints: Option<P<ConstraintTracker>>,
    self_solution: Option<&ConstraintSolution>,
    recursion_count: u32,
) -> bool {
    let src_object_to_bind = if is_class(src_class) {
        Some(ClassType::clone_as_instance(ClassType(src_class), true))
    } else {
        None
    };
    let dest_object_to_bind = ClassType::clone_as_instance(dest_class, true);
    let mut is_assignable = true;
    // Each entry is (getFunction, missingDiagMsg, incompatibleDiagMsg).
    let accessors: [(
        fn(ClassType) -> Option<P<Type>>,
        fn() -> String,
        fn() -> String,
    ); 3] = [
        (
            |c| {
                c.d()
                    .priv_
                    .borrow()
                    .cold().fget_info
                    .as_ref()
                    .map(|info| info.method_type)
            },
            LocAddendum::missing_getter,
            LocAddendum::incompatible_getter,
        ),
        (
            |c| {
                c.d()
                    .priv_
                    .borrow()
                    .cold().fset_info
                    .as_ref()
                    .map(|info| info.method_type)
            },
            LocAddendum::missing_setter,
            LocAddendum::incompatible_setter,
        ),
        (
            |c| {
                c.d()
                    .priv_
                    .borrow()
                    .cold().fdel_info
                    .as_ref()
                    .map(|info| info.method_type)
            },
            LocAddendum::missing_deleter,
            LocAddendum::incompatible_deleter,
        ),
    ];

    for (get_function, missing_diag_msg, _incompatible_diag_msg) in accessors {
        let dest_access_type = get_function(dest_property_type);

        // Handle both single-function accessors and overloaded accessors (e.g.
        // overloaded property setters). assignType and bindFunctionToClassOrObject
        // both understand OverloadedType, so the comparison logic below works for
        // either form.
        if let Some(mut dest_access_type) = dest_access_type
            && (is_function(dest_access_type) || is_overloaded(dest_access_type))
        {
            let src_access_type = get_function(src_property_type);

            let src_access_type = match src_access_type {
                Some(src_access_type)
                    if is_function(src_access_type) || is_overloaded(src_access_type) =>
                {
                    src_access_type
                }
                _ => {
                    if let Some(diag) = diag {
                        diag.add_message(missing_diag_msg());
                    }
                    is_assignable = false;
                    continue;
                }
            };

            evaluator.infer_return_type_if_necessary(src_access_type);
            evaluator.infer_return_type_if_necessary(dest_access_type);

            // If the caller provided a "self" TypeVar context, replace any Self types.
            // This is needed during protocol matching.
            if let Some(self_solution) = self_solution {
                dest_access_type = apply_solved_type_vars(
                    dest_access_type,
                    self_solution,
                    &ApplyTypeVarOptions::default(),
                );
            }

            let bound_dest_access_type = evaluator
                .bind_function_to_class_or_object(
                    Some(dest_object_to_bind),
                    dest_access_type,
                    /* memberClass */ None,
                    /* treatConstructorAsClassMethod */ false,
                    /* firstParamType */ None,
                    diag.map(|diag| diag.create_addendum()),
                    recursion_count,
                )
                .unwrap_or(dest_access_type);

            let bound_src_access_type = evaluator
                .bind_function_to_class_or_object(
                    src_object_to_bind,
                    src_access_type,
                    /* memberClass */ None,
                    /* treatConstructorAsClassMethod */ false,
                    /* firstParamType */ None,
                    diag.map(|diag| diag.create_addendum()),
                    recursion_count,
                )
                .unwrap_or(src_access_type);

            if !evaluator.assign_type(
                bound_dest_access_type,
                bound_src_access_type,
                diag,
                constraints,
                AssignTypeFlags::Default,
                recursion_count,
            ) {
                is_assignable = false;
            }
        }
    }

    is_assignable
}
